CREATE TABLE `replica_identity` (
	`slot` integer PRIMARY KEY,
	`replica_id` text NOT NULL UNIQUE,
	`workspace_id` text NOT NULL,
	`created_at` integer NOT NULL
);

CREATE TABLE `artist_credit` (
	`id` text PRIMARY KEY,
	`policy_version` integer NOT NULL,
	`revision` integer NOT NULL
);

CREATE TABLE `library_root` (
	`id` text PRIMARY KEY,
	`owner_id` text NOT NULL,
	`path` text NOT NULL UNIQUE,
	`created_at` integer NOT NULL
);

CREATE TABLE `__new_library_root` (
	`id` text PRIMARY KEY,
	`owner_id` text,
	`path` text NOT NULL UNIQUE,
	`created_at` integer NOT NULL
);

CREATE TABLE `credential` (
	`provider_account_id` text PRIMARY KEY,
	`values` text NOT NULL,
	CONSTRAINT `fk_credential_provider_account_id_provider_account_id_fk` FOREIGN KEY (`provider_account_id`) REFERENCES `provider_account`(`id`) ON DELETE CASCADE
);

CREATE TABLE `provider_account` (
	`id` text PRIMARY KEY,
	`user_id` text NOT NULL,
	`provider` text NOT NULL,
	`display_name` text NOT NULL,
	`created_at` integer NOT NULL,
	CONSTRAINT `fk_provider_account_user_id_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON DELETE CASCADE
);

CREATE TABLE `device` (
	`id` text PRIMARY KEY,
	`user_id` text NOT NULL,
	`name` text NOT NULL,
	`token_hash` text NOT NULL UNIQUE,
	`created_at` integer NOT NULL,
	CONSTRAINT `fk_device_user_id_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON DELETE CASCADE
);

CREATE TABLE `user` (
	`id` text PRIMARY KEY,
	`username` text NOT NULL UNIQUE,
	`password_hash` text NOT NULL,
	`role` text NOT NULL,
	`created_at` integer NOT NULL
);

CREATE UNIQUE INDEX `provider_account_user_idx` ON `provider_account` (`user_id`,`provider`);

CREATE INDEX `device_user_idx` ON `device` (`user_id`);

CREATE TABLE `isrc_lookup` (
	`isrc` text PRIMARY KEY,
	`recordings` text NOT NULL,
	`checked_at` integer NOT NULL
);

CREATE TABLE `sync_rejection` (
	`replica_id` text NOT NULL,
	`mutation_id` integer NOT NULL,
	`reason` text NOT NULL,
	CONSTRAINT `sync_rejection_pk` PRIMARY KEY(`replica_id`, `mutation_id`)
);

UPDATE `replica_identity` SET `change_seq` = 1, `epoch` = lower(
	hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' ||
	substr('89ab', 1 + abs(random()) % 4, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6))
);

CREATE TABLE `artist_lookup` (
	`name_key` text PRIMARY KEY,
	`artists` text NOT NULL,
	`checked_at` integer NOT NULL
);

UPDATE `library_remote_playlist` SET
  `name` = (SELECT `name` FROM `playlist` WHERE `playlist`.`id` = `library_remote_playlist`.`playlist_id`),
  `snapshot` = (
    SELECT json_group_array(`recording_id` ORDER BY `position`, `id`) FROM `playlist_entry`
    WHERE `playlist_entry`.`playlist_id` = `library_remote_playlist`.`playlist_id` AND `deleted` = 0
  );

CREATE TABLE `output_setting` (
	`output_id` text PRIMARY KEY,
	`delay_ms` integer NOT NULL
);

-- Migrations run in a transaction, where `foreign_keys` cannot change. Dropping a parent table
-- deletes its child rows, so they wait in a copy.
CREATE TABLE `__keep_credential` AS SELECT * FROM `credential`;

CREATE TABLE `__new_device` (
	`id` text PRIMARY KEY,
	`name` text NOT NULL,
	`token_hash` text NOT NULL UNIQUE,
	`created_at` integer NOT NULL
);

INSERT INTO `song_artist` (`recording_id`, `position`, `artist_id`, `name`, `join_phrase`)
SELECT `recording`.`id`, `n`.`position`, `n`.`artist_id`, `n`.`credited_as`, `n`.`join_phrase`
FROM `recording` JOIN `artist_credit_name` AS `n` ON `n`.`artist_credit_id` = `recording`.`artist_credit_id`;
